<tr><td>质控水平 1 (L1)</td><td>${(p.l1_mean||0).toFixed(2)} ${U(g)}</td><td>${(p.l1_sd||0).toFixed(2)} ${U(g)}</td><td>${(p.l1_sd||0).toFixed(2)} ${U(g)}</td><td>${G.toFixed(2)}%</td><td>${p.l1_n||0}</td></tr>
